const reminderDefaults={enabled:true,frequency:'daily',days:[1,2,3,4,5,6,0],times:['08:00','18:00'],interval:3,windowStart:'08:00',windowEnd:'20:00',advance:1,summary:true,overdue:true,quiet:true,quietStart:'22:00',quietEnd:'07:00',timezone:'America/Sao_Paulo',categories:[]};
const reminderDays=[[1,'Seg'],[2,'Ter'],[3,'Qua'],[4,'Qui'],[5,'Sex'],[6,'Sáb'],[0,'Dom']];
function reminderSettings(){
  const stored=db.settings.notifications||{}, n={...reminderDefaults,...stored};
  n.times=Array.isArray(stored.times)&&stored.times.length?stored.times.slice(0,3):[...reminderDefaults.times];
  n.days=Array.isArray(stored.days)?stored.days:[...reminderDefaults.days];
  n.categories=Array.isArray(stored.categories)?stored.categories:[];
  return n;
}
function notificationSettings(){
  const n=reminderSettings(),checked=v=>v?'checked':'', options=(items,value)=>items.map(([key,label])=>`<option value="${key}" ${String(value)===String(key)?'selected':''}>${label}</option>`).join('');
  return `<section class="card reminder-card"><div class="row between wrap"><div><h2>Notificações e lembretes</h2><p class="muted">Escolha como você quer ser lembrada.</p></div><span class="badge">Envio ainda não conectado</span></div><form id="notificationform" class="form"><label class="reminder-toggle"><span><strong>Receber lembretes</strong><small>Guardar suas preferências para ativar o envio depois.</small></span><input name="enabled" type="checkbox" ${checked(n.enabled)}></label><fieldset id="reminderfields" ${n.enabled?'':'disabled'}><div class="reminder-grid"><div class="form"><label>Frequência<select name="frequency" id="reminderfrequency">${options([['daily','Todos os dias'],['weekdays','Segunda a sexta'],['custom','Dias escolhidos'],['interval','Repetir a cada algumas horas']],n.frequency)}</select></label><div id="reminderdays" ${n.frequency==='custom'?'':'hidden'}><span class="field-caption">Dias da semana</span><div class="reminder-days">${reminderDays.map(([day,label])=>`<label><input name="days" type="checkbox" value="${day}" ${checked(n.days.includes(day))}><span>${label}</span></label>`).join('')}</div></div><div id="remindertimes" ${n.frequency==='interval'?'hidden':''}><span class="field-caption">Horários dos avisos · até 3 por dia</span><div class="reminder-times">${[0,1,2].map(i=>`<label>${i+1}º aviso${i===0?'':' · opcional'}<input type="time" name="time${i}" value="${esc(n.times[i]||'')}" ${i===0&&n.frequency!=='interval'?'required':''}></label>`).join('')}</div></div><div id="reminderinterval" class="form" ${n.frequency==='interval'?'':'hidden'}><label>Repetir a cada<select name="interval">${options([[1,'1 hora'],[2,'2 horas'],[3,'3 horas'],[4,'4 horas'],[6,'6 horas']],n.interval)}</select></label><div class="pair"><label>Começar às<input type="time" name="windowStart" value="${esc(n.windowStart)}"></label><label>Terminar às<input type="time" name="windowEnd" value="${esc(n.windowEnd)}"></label></div><small>Repetições dentro dessa faixa, todos os dias.</small></div><label>Antecedência da tarefa<select name="advance">${options([[0,'Somente no dia'],[1,'1 dia antes e no dia'],[2,'2 dias antes e no dia'],[7,'1 semana antes e no dia']],n.advance)}</select></label><label>Fuso horário<select name="timezone">${options([['America/Sao_Paulo','Brasília · São Paulo'],['America/Manaus','Manaus'],['America/Rio_Branco','Rio Branco'],['America/Noronha','Fernando de Noronha'],['Europe/Lisbon','Lisboa']],n.timezone)}</select></label></div><div class="form"><label class="reminder-option"><input name="summary" type="checkbox" ${checked(n.summary)}><span>Incluir resumo das tarefas do dia</span></label><label class="reminder-option"><input name="overdue" type="checkbox" ${checked(n.overdue)}><span>Continuar lembrando tarefas atrasadas</span></label><label class="reminder-option"><input id="reminderquiet" name="quiet" type="checkbox" ${checked(n.quiet)}><span>Não incomodar durante o descanso</span></label><div id="reminderquiettimes" class="pair" ${n.quiet?'':'hidden'}><label>Silenciar a partir de<input name="quietStart" type="time" value="${esc(n.quietStart)}"></label><label>Voltar a avisar às<input name="quietEnd" type="time" value="${esc(n.quietEnd)}"></label></div><small>Os avisos durante o descanso serão ignorados. O modo Foco do iPhone também pode silenciá-los.</small><div><span class="field-caption">Categorias que podem gerar lembretes</span><small>Sem seleção, todas as categorias são incluídas.</small><div class="reminder-categories">${db.categories.map(c=>`<label class="reminder-option"><input name="categories" type="checkbox" value="${esc(c.id)}" ${checked(n.categories.includes(c.id))}><span>${esc(c.emoji+' '+c.name)}</span></label>`).join('')}</div></div><div class="notice">Estas preferências são salvas neste aparelho. As notificações no iPhone só serão enviadas após conectar o serviço de envio, instalar o app na Tela de Início e autorizar as notificações. Tarefas concluídas não receberão lembretes.</div></div></div></fieldset><p id="reminderfeedback" role="status" aria-live="polite"></p><div class="row wrap"><button class="primary" type="submit">Salvar preferências</button><small>Você pode mudar essas escolhas a qualquer momento.</small></div></form></section>`;
}
function bindNotificationSettings(){
  const form=$('#notificationform');if(!form)return;
  const sync=()=>{const enabled=form.elements.enabled.checked,frequency=form.elements.frequency.value;$('#reminderfields').disabled=!enabled;$('#reminderdays').hidden=frequency!=='custom';$('#remindertimes').hidden=frequency==='interval';$('#reminderinterval').hidden=frequency!=='interval';form.elements.time0.required=enabled&&frequency!=='interval';$('#reminderquiettimes').hidden=!form.elements.quiet.checked;};
  form.onchange=()=>{sync();$('#reminderfeedback').textContent='Alterações ainda não salvas.'};sync();
  form.onsubmit=e=>{
    e.preventDefault();const feedback=$('#reminderfeedback'),fields=$('#reminderfields'),wasDisabled=fields.disabled;fields.disabled=false;const f=new FormData(form);fields.disabled=wasDisabled;
    const n={enabled:f.has('enabled'),frequency:f.get('frequency'),days:f.getAll('days').map(Number),times:[0,1,2].map(i=>f.get('time'+i)).filter(Boolean),interval:Number(f.get('interval')),windowStart:f.get('windowStart'),windowEnd:f.get('windowEnd'),advance:Number(f.get('advance')),summary:f.has('summary'),overdue:f.has('overdue'),quiet:f.has('quiet'),quietStart:f.get('quietStart'),quietEnd:f.get('quietEnd'),timezone:f.get('timezone'),categories:f.getAll('categories')};
    const error=t=>{feedback.textContent=t;feedback.className='negative'};
    if(n.enabled&&n.frequency==='custom'&&!n.days.length)return error('Escolha pelo menos um dia da semana.');
    if(n.enabled&&n.frequency!=='interval'&&!n.times.length)return error('Escolha pelo menos um horário.');
    if(new Set(n.times).size!==n.times.length)return error('Escolha horários diferentes para cada aviso.');
    if(n.enabled&&n.frequency==='interval'&&(!n.windowStart||!n.windowEnd||n.windowEnd<=n.windowStart))return error('A faixa de repetição deve terminar depois do horário inicial.');
    if(n.enabled&&n.quiet&&(!n.quietStart||!n.quietEnd||n.quietStart===n.quietEnd))return error('Escolha horários diferentes para o início e o fim do descanso.');
    const previous=db.settings.notifications;db.settings.notifications=n;
    if(!save()){if(previous)db.settings.notifications=previous;else delete db.settings.notifications;return error('Não foi possível salvar as preferências.');}
    feedback.className='positive';feedback.textContent=n.enabled?'Preferências salvas. O envio ainda aguarda integração.':'Preferências salvas. Lembretes desativados.';
  };
}
